-- =====================================================================
-- Walk Metro Manila — D1 (SQLite) schema
--
--   npx wrangler d1 migrations apply wmm-db --local     (local dev)
--   npx wrangler d1 migrations apply wmm-db --remote    (production)
--
-- Differences from the old Postgres schema:
--   * ids are text UUIDs generated by the default expression below
--   * timestamps are ISO-8601 UTC strings (sortable as text)
--   * `tags` and `route` are JSON stored as text
--   * there is no RLS: every admin route checks Cloudflare Access itself
--   * full-text search uses SQLite FTS5 (<table>_fts) kept in sync by triggers
-- =====================================================================

-- ---------------------------------------------------------------------
-- categories
-- ---------------------------------------------------------------------
CREATE TABLE categories (
  id          TEXT PRIMARY KEY DEFAULT (
    lower(
      hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' ||
      substr(hex(randomblob(2)), 2) || '-' ||
      substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' ||
      hex(randomblob(6))
    )
  ),
  name        TEXT NOT NULL UNIQUE,
  slug        TEXT NOT NULL UNIQUE,
  description TEXT,
  is_active   INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_categories_is_active ON categories (is_active);

-- ---------------------------------------------------------------------
-- videos
-- ---------------------------------------------------------------------
CREATE TABLE videos (
  id                     TEXT PRIMARY KEY,

  title                  TEXT NOT NULL,
  description            TEXT,

  video_url              TEXT NOT NULL,
  thumbnail_url          TEXT,
  storage_path           TEXT,   -- key inside the "videos" prefix of the R2 bucket
  thumbnail_storage_path TEXT,   -- key inside the "thumbnails" prefix

  location               TEXT,
  street                 TEXT,
  barangay               TEXT,
  city                   TEXT,
  province               TEXT DEFAULT 'Metro Manila',
  region                 TEXT DEFAULT 'NCR',

  latitude               REAL CHECK (latitude  IS NULL OR latitude  BETWEEN -90  AND 90),
  longitude              REAL CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  -- {mode, points: [[lat,lng]...], path: [[lat,lng]...], distance_m}
  route                  TEXT CHECK (route IS NULL OR json_valid(route)),

  recorded_at            TEXT,
  uploaded_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  duration_seconds       INTEGER,
  file_size_bytes        INTEGER,

  category_id            TEXT REFERENCES categories (id) ON DELETE SET NULL,
  tags                   TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tags)),

  views                  INTEGER NOT NULL DEFAULT 0,
  status                 TEXT NOT NULL DEFAULT 'draft'
                           CHECK (status IN ('draft', 'published', 'private', 'deleted')),

  created_by             TEXT,   -- email of the Cloudflare Access user
  deleted_at             TEXT,   -- soft delete marker (recycle bin)

  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_videos_status      ON videos (status);
CREATE INDEX idx_videos_city        ON videos (city COLLATE NOCASE);
CREATE INDEX idx_videos_category_id ON videos (category_id);
CREATE INDEX idx_videos_recorded_at ON videos (recorded_at DESC);
CREATE INDEX idx_videos_created_at  ON videos (created_at DESC);
CREATE INDEX idx_videos_deleted_at  ON videos (deleted_at);

-- ---------------------------------------------------------------------
-- photos
-- ---------------------------------------------------------------------
CREATE TABLE photos (
  id              TEXT PRIMARY KEY,

  title           TEXT NOT NULL,
  description     TEXT,

  image_url       TEXT NOT NULL,
  storage_path    TEXT,   -- key inside the "photos" prefix of the R2 bucket

  location        TEXT,
  street          TEXT,
  barangay        TEXT,
  city            TEXT,
  province        TEXT DEFAULT 'Metro Manila',
  region          TEXT DEFAULT 'NCR',

  latitude        REAL CHECK (latitude  IS NULL OR latitude  BETWEEN -90  AND 90),
  longitude       REAL CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),

  recorded_at     TEXT,
  uploaded_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  file_size_bytes INTEGER,

  category_id     TEXT REFERENCES categories (id) ON DELETE SET NULL,
  tags            TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tags)),

  views           INTEGER NOT NULL DEFAULT 0,
  status          TEXT NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'published', 'private', 'deleted')),

  created_by      TEXT,
  deleted_at      TEXT,

  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_photos_status      ON photos (status);
CREATE INDEX idx_photos_city        ON photos (city COLLATE NOCASE);
CREATE INDEX idx_photos_category_id ON photos (category_id);
CREATE INDEX idx_photos_recorded_at ON photos (recorded_at DESC);
CREATE INDEX idx_photos_created_at  ON photos (created_at DESC);
CREATE INDEX idx_photos_deleted_at  ON photos (deleted_at);

-- ---------------------------------------------------------------------
-- video_views: one row per (video, viewer) so a viewer counts once.
-- ---------------------------------------------------------------------
CREATE TABLE video_views (
  video_id   TEXT NOT NULL REFERENCES videos (id) ON DELETE CASCADE,
  viewer_key TEXT NOT NULL,
  viewed_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (video_id, viewer_key)
) WITHOUT ROWID;

-- ---------------------------------------------------------------------
-- Full-text search (FTS5). One row per video / photo, kept in sync by
-- triggers. Replaces the Postgres tsvector column + GIN index.
-- ---------------------------------------------------------------------
CREATE VIRTUAL TABLE videos_fts USING fts5(
  video_id UNINDEXED,
  content,
  tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER trg_videos_fts_insert AFTER INSERT ON videos
BEGIN
  INSERT INTO videos_fts (video_id, content) VALUES (
    new.id,
    coalesce(new.title, '') || ' ' || coalesce(new.description, '') || ' ' ||
    coalesce(new.location, '') || ' ' || coalesce(new.street, '') || ' ' ||
    coalesce(new.barangay, '') || ' ' || coalesce(new.city, '') || ' ' ||
    coalesce(new.tags, '')
  );
END;

CREATE TRIGGER trg_videos_fts_update
AFTER UPDATE OF title, description, location, street, barangay, city, tags ON videos
BEGIN
  DELETE FROM videos_fts WHERE video_id = old.id;
  INSERT INTO videos_fts (video_id, content) VALUES (
    new.id,
    coalesce(new.title, '') || ' ' || coalesce(new.description, '') || ' ' ||
    coalesce(new.location, '') || ' ' || coalesce(new.street, '') || ' ' ||
    coalesce(new.barangay, '') || ' ' || coalesce(new.city, '') || ' ' ||
    coalesce(new.tags, '')
  );
END;

CREATE TRIGGER trg_videos_fts_delete AFTER DELETE ON videos
BEGIN
  DELETE FROM videos_fts WHERE video_id = old.id;
END;

CREATE VIRTUAL TABLE photos_fts USING fts5(
  photo_id UNINDEXED,
  content,
  tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER trg_photos_fts_insert AFTER INSERT ON photos
BEGIN
  INSERT INTO photos_fts (photo_id, content) VALUES (
    new.id,
    coalesce(new.title, '') || ' ' || coalesce(new.description, '') || ' ' ||
    coalesce(new.location, '') || ' ' || coalesce(new.street, '') || ' ' ||
    coalesce(new.barangay, '') || ' ' || coalesce(new.city, '') || ' ' ||
    coalesce(new.tags, '')
  );
END;

CREATE TRIGGER trg_photos_fts_update
AFTER UPDATE OF title, description, location, street, barangay, city, tags ON photos
BEGIN
  DELETE FROM photos_fts WHERE photo_id = old.id;
  INSERT INTO photos_fts (photo_id, content) VALUES (
    new.id,
    coalesce(new.title, '') || ' ' || coalesce(new.description, '') || ' ' ||
    coalesce(new.location, '') || ' ' || coalesce(new.street, '') || ' ' ||
    coalesce(new.barangay, '') || ' ' || coalesce(new.city, '') || ' ' ||
    coalesce(new.tags, '')
  );
END;

CREATE TRIGGER trg_photos_fts_delete AFTER DELETE ON photos
BEGIN
  DELETE FROM photos_fts WHERE photo_id = old.id;
END;
